"""Final connected graph, Metal shader and original-shadow-input validation; no GPU benchmark."""
import unreal,json,time
from pathlib import Path
R=Path(unreal.Paths.project_dir()).resolve();E=unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem);assert not E.get_game_world()and E.get_editor_world().get_name()=='Dev_BiomeTestMap_V1';assert not unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages()and not unreal.EditorLoadingAndSavingUtils.get_dirty_content_packages();M=unreal.MaterialEditingLibrary;rows=[]
for name in ['M_V2_CrownReveal_Dense','M_V2_BarkRevealBase_Dense']:
 m=unreal.load_asset('/Game/Environment/BiomeTestV1/DenseForestV11/'+name);f=next(x for x in M.get_material_expressions(m)if isinstance(x,unreal.MaterialExpressionCustom)and'Only upper canopy'in str(x.get_editor_property('desc')));declared=[str(i.get_editor_property('input_name'))for i in f.get_editor_property('inputs')];wired=M.get_inputs_for_material_expression(m,f);assert declared==['P','T','S','C']and len(wired)==4 and all(wired)
 mask=M.get_material_property_input_node(m,unreal.MaterialProperty.MP_OPACITY_MASK);assert isinstance(mask,unreal.MaterialExpressionShadowReplace);paths=M.get_inputs_for_material_expression(m,mask);assert len(paths)==2 and all(paths);assert paths[0]!=paths[1];assert not isinstance(paths[1],unreal.MaterialExpressionShadowReplace)
 # Final complete graph recompilation, unlike automatic previews while adding an input.
 M.recompile_material(m);st=M.get_statistics(m);vs=st.get_editor_property('num_vertex_shader_instructions');ps=st.get_editor_property('num_pixel_shader_instructions');assert vs>0 and ps>0,('No own compiled shader statistics',name,vs,ps);assert unreal.EditorAssetLibrary.save_loaded_asset(m,False);rows.append({'material':m.get_path_name(),'connected_inputs':declared,'shadow_switch_inputs':[x.get_path_name()for x in paths],'own_shader_statistics_nonzero':True})
assert not unreal.EditorLoadingAndSavingUtils.get_dirty_content_packages();(R/'Saved/BiomeTestV11/ForestMaterialValidation.json').write_text(json.dumps({'passed':True,'rows':rows,'no_benchmark':True,'note':'Earlier missing-C warnings arose during intermediate graph editing before wiring; final fully connected graphs recompiled explicitly. Verify fresh-session log and real images too.'},indent=2))
